// makeMedia generates a tiny probeable video file at path via ffmpeg's lavfi
// testsrc. It t.Skip's the calling test if ffmpeg is unavailable, so the
// ffprobe-dependent tests port cleanly to CI without ffmpeg.
func makeMedia(t *testing.T, path string) {
	t.Helper()
	_ = exec.Command("ffmpeg",
		"-f", "lavfi",
		"-i", "testsrc=duration=0.3:size=16x16:rate=10",
		"-loglevel", "error",
		"-y",
		filepath.Clean(path),
	).Run()
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skipf("ffmpeg unavailable: cannot generate media fixture for %s", path)
	}
}

